window.ESS_SLIDE_QUIZ = {"intro":[{"s":1,"e":14,"q":"How is your IB ESS SL final grade weighted across Paper 1, Paper 2, and the IA?","opts":["Paper 1 25%, Paper 2 50%, IA 25%","Paper 1 50%, Paper 2 25%, IA 25%","Paper 1 40%, Paper 2 40%, IA 20%","Paper 1 30%, Paper 2 50%, IA 20%"],"a":0,"exp":"External assessment is 75% (Paper 1 resource booklet 1h = 25%, Paper 2 short-answer + essay 2h = 50%), and the IA is 25% for SL."},{"s":1,"e":14,"q":"In Grade 11 ESS, what percentage boundary is required for a Grade 7, and how much do Semester Exams weigh?","opts":["80% boundary, 30% Exams","85% boundary, 40% Exams","90% boundary, 50% Exams","73% boundary, 40% Exams"],"a":1,"exp":"Grade 7 starts at 85% (Grade 6 at 73%). Semester weighting: 10% Quizzes, 20% Lab/IA, 30% Unit Tests, and 40% Exams."}],"e11":[{"s":1,"e":19,"q":"According to 1.1.1-1.1.2, what forms an individual's environmental perspective?","opts":["Personal and collective assumptions, values, and beliefs shaped by norms, science, laws, and experience","Only scientific data published in peer-reviewed journals","Inherited genetic traits alone","National GDP per capita"],"a":0,"exp":"Perspectives grow from personal and collective assumptions, values, and beliefs, informed by sociocultural norms, science, laws, religion, economics, and lived experience."},{"s":20,"e":30,"q":"What is the difference between intrinsic value and instrumental value in ESS?","opts":["Intrinsic value is market price; instrumental value is aesthetic beauty","Intrinsic value is worth simply for existing; instrumental value is usefulness to humans","Both mean monetary profit from timber","Instrumental value applies only to endangered species"],"a":1,"exp":"Intrinsic value attaches worth to nature simply for what it is, while instrumental value measures its usefulness to humans."},{"s":31,"e":36,"q":"In an Environmental Value System (EVS) systems model, which of these is an OUTPUT rather than an input?","opts":["Media exposure and education","Religious beliefs and cultural norms","Decisions, policies, and lifestyle actions","Scientific understandings"],"a":2,"exp":"Education, media, culture, religion, and science are inputs; decisions, evaluations, policies, and actions are outputs."},{"s":37,"e":47,"q":"Which EVS trusts human innovation, green technology, and market mechanisms to overcome ecological limits?","opts":["Ecocentrism","Deep ecology","Anthropocentrism","Technocentrism"],"a":3,"exp":"Technocentrism trusts technology and human ingenuity to solve environmental problems without halting economic growth."},{"s":37,"e":47,"q":"How does an anthropocentric worldview typically approach environmental problems?","opts":["By treating humans as managers who use laws, taxes, and treaties to sustain human well-being","By rejecting all government regulation","By assigning equal legal rights to rocks and rivers over people","By waiting for geoengineering to fix every issue automatically"],"a":0,"exp":"Anthropocentrism centers on human well-being and favors environmental regulation, taxes, legislation, and international agreements."},{"s":48,"e":55,"q":"What tools are used in 1.1.5 to investigate the environmental perspectives of a social group?","opts":["Lincoln Index capture-mark-recapture","Values surveys and questionnaires","Belt transects","Calorimetry bombs"],"a":1,"exp":"Values surveys and questionnaires reveal perspectives and value indicators across different age groups or communities."}],"e12":[{"s":1,"e":7,"q":"What is the main limitation of using a model to study an environmental system?","opts":["Models cannot be drawn as diagrams","Simplification involves approximation and therefore loss of accuracy","Models only work for closed systems","Models ignore all flows"],"a":1,"exp":"Models simplify complex reality so we can predict change, which always trades off some accuracy through approximation."},{"s":8,"e":23,"q":"What are emergent properties in a system (1.2.15)?","opts":["New species migrating into a pond","Whole-system behaviors arising from component interactions that cannot be seen in isolated parts","Inputs crossing a closed boundary","Sudden errors in a computer simulation"],"a":1,"exp":"Emergent properties appear only when system parts interact together as a whole."},{"s":24,"e":37,"q":"In a systems diagram, which process is a TRANSFORMATION rather than a transfer?","opts":["Water flowing downstream in a river","A deer eating grass","Photosynthesis turning CO2 and H2O into glucose","Wind blowing soil dust"],"a":2,"exp":"Transfers move matter/energy without changing form; transformations change chemical state or energy form (like photosynthesis)."},{"s":24,"e":37,"q":"In standard systems diagram notation, what do rectangular boxes and arrows represent?","opts":["Boxes = flows; arrows = boundaries","Boxes = storages (stocks); arrows = flows (inputs, outputs, processes)","Boxes = tipping points; arrows = species","Boxes = open systems; arrows = closed systems"],"a":1,"exp":"Rectangles represent storages (stocks of matter/energy), and directional arrows represent flows into, through, and out of the system."},{"s":38,"e":46,"q":"Why is an ecosystem classified as an OPEN system, whereas Earth (excluding meteorites) is mostly a CLOSED system?","opts":["Ecosystems exchange both matter and energy; Earth exchanges energy but virtually no matter","Ecosystems exchange energy only; Earth exchanges matter only","Open systems have no outputs","Closed systems have no sunlight inputs"],"a":0,"exp":"Open systems exchange both matter and energy across their boundaries; closed systems exchange energy only."},{"s":47,"e":60,"q":"Why is melting Arctic sea ice an example of POSITIVE feedback?","opts":["It benefits polar bears","Melting exposes dark ocean water (lower albedo), absorbing more heat and amplifying warming","It stabilizes global temperatures","It reverses predator-prey oscillations"],"a":1,"exp":"Positive feedback amplifies the initial disturbance, pushing the climate away from equilibrium toward a tipping point."},{"s":47,"e":60,"q":"How does a NEGATIVE feedback loop affect an ecosystem?","opts":["It amplifies change until collapse","It counteracts deviation and maintains steady-state equilibrium","It eliminates all energy losses","It turns an open system into an isolated system"],"a":1,"exp":"Negative feedback inhibits or reverses change (e.g. predator-prey cycles), stabilizing the system around equilibrium."},{"s":61,"e":67,"q":"What does hysteresis mean after an ecosystem crosses a tipping point (1.2.12)?","opts":["The system recovers instantly once stress stops","Returning to the original state requires far greater effort or much lower stress than caused the collapse","Species diversity doubles after collapse","Negative feedback becomes unnecessary"],"a":1,"exp":"Hysteresis means the recovery path is asymmetrical: restoring an altered regime takes much lower stress or extra intervention."},{"s":68,"e":78,"q":"Which two internal features most directly increase an ecosystem's resilience?","opts":["Low biodiversity and tiny storages","High biodiversity and large storages","Positive feedback and monoculture","Short food chains and fast deforestation"],"a":1,"exp":"High diversity (functional redundancy) and large storages buffer shocks and help avoid tipping points."}],"e13":[{"s":1,"e":19,"q":"How does a STRONG sustainability model differ from a WEAK sustainability Venn diagram?","opts":["Strong sustainability places Economy inside Society, and both nested inside Nature","Weak sustainability bans economic growth","Strong sustainability excludes social equity","They are identical models"],"a":0,"exp":"Strong sustainability nests economy inside society inside the biosphere, showing the economy depends on healthy ecosystems."},{"s":20,"e":39,"q":"Why is GDP an inadequate measure of sustainable development?","opts":["It excludes all industrial output","It measures market transactions only and ignores natural capital depletion and inequality","It only tracks carbon footprints","It cannot be compared across countries"],"a":1,"exp":"GDP ignores environmental degradation, unpaid ecosystem services, inequality, and transboundary pollution from imports."},{"s":40,"e":55,"q":"What happens when a country's Ecological Footprint exceeds its biocapacity?","opts":["Steady-state sustainability","Ecological overshoot","Higher biodiversity","Negative feedback stabilization"],"a":1,"exp":"When resource and waste demand exceeds ecosystem regeneration capacity (biocapacity), the system enters ecological overshoot."},{"s":56,"e":65,"q":"What is the core principle of Environmental Justice (1.3.9)?","opts":["Only wealthy countries should cut emissions","Everyone has the right to a pollution-free environment and fair access to resources regardless of race or income","GDP growth must come before clean water","Nature has no value unless priced in markets"],"a":1,"exp":"Environmental justice requires equitable access to natural resources and protection from pollution for all communities."},{"s":66,"e":74,"q":"What is the goal of the Planetary Boundaries model (1.3.19)?","opts":["To maximize fossil-fuel extraction","To define a safe operating space across 9 Earth-system thresholds and avoid tipping points","To replace all science with GDP","To rank countries by population size"],"a":1,"exp":"Crossing planetary boundaries (climate change, biosphere integrity, biogeochemical flows, etc.) risks abrupt irreversible Earth-system shifts."},{"s":75,"e":93,"q":"In Doughnut Economics, what lies inside the inner ring and outside the outer ring?","opts":["Inner: social shortfall; Outer: ecological overshoot beyond planetary boundaries","Inner: overshoot; Outer: GDP surplus","Inner: biodiversity; Outer: biocapacity","Inner: circular economy; Outer: recycling"],"a":0,"exp":"Falling inside the inner ring means unmet human needs (shortfall); pushing past the outer ceiling causes ecological overshoot."},{"s":75,"e":93,"q":"In the Circular Economy Butterfly Diagram, what do the left and right wings represent?","opts":["Left: GDP; Right: taxes","Left: biological cycle (composting/regeneration); Right: technical cycle (repair, reuse, recycle)","Left: fossil fuels; Right: landfills","Left: imports; Right: exports"],"a":1,"exp":"The biological wing safely returns biodegradable nutrients to nature; the technical wing keeps finite materials circulating."},{"s":94,"e":98,"q":"How does citizen science support sustainability management (1.3.16)?","opts":["By replacing all peer review","Volunteers help collect large-scale biodiversity or pollution data, raising public awareness and monitoring","By privatizing national parks","By removing abiotic measurements"],"a":1,"exp":"Citizen science engages communities in gathering ecological data across wide geographic areas at low cost."}],"e21":[{"s":1,"e":25,"q":"By the biological species concept, two organisms belong to the same species if they:","opts":["Live in the same habitat","Can interbreed naturally to produce fertile offspring","Share the same trophic level","Eat the same food"],"a":1,"exp":"A biological species consists of organisms capable of interbreeding to produce viable, fertile offspring."},{"s":26,"e":49,"q":"Why does an S-curve (logistic growth) level off around carrying capacity K instead of rising forever like a J-curve?","opts":["Abiotic factors disappear","Density-dependent limiting factors (competition, predation, disease) slow growth and stabilize the population","Photosynthesis stops at carrying capacity","Individuals become immortal"],"a":1,"exp":"Negative feedback from density-dependent factors reduces birth rates or raises death rates as population approaches K."},{"s":50,"e":73,"q":"When is a BELT TRANSECT better than random quadrats?","opts":["Counting fast-moving birds in a forest","Measuring how plant distribution changes across an environmental gradient (zonation)","Estimating deep-ocean fish stocks","Measuring dissolved oxygen only"],"a":1,"exp":"Belt transects systematically sample along a gradient (such as rocky shore zonation or forest edge to deep shade)."},{"s":74,"e":79,"q":"In a Lincoln Index study, n1 = 80, n2 = 65, m2 = 20. What is N, and what happens if marks make animals easier for predators to eat?","opts":["N = 260; visible marks lower m2 and OVERESTIMATE N","N = 260; visible marks raise m2 and UNDERESTIMATE N","N = 145; no bias occurs","N = 1,040; marks fall off"],"a":0,"exp":"N = (80 x 65) / 20 = 260. Higher predation on marked animals shrinks m2 in the denominator, inflating estimated N."},{"s":80,"e":90,"q":"How does a habitat differ from an ecological niche?","opts":["Habitat is where a species lives; niche is its full abiotic and biotic role","Niche is the physical place; habitat is the food eaten","Only producers have niches","They mean the same thing"],"a":0,"exp":"Habitat is the physical location; niche covers all resources, abiotic tolerances, and interactions the species has."},{"s":91,"e":103,"q":"What happens in a trophic cascade if a keystone predator is removed?","opts":["Nothing changes","Herbivore prey populations explode, overgrazing producers and collapsing ecosystem stability","Primary producers double permanently","Biomagnification stops"],"a":1,"exp":"Removing a keystone predator releases prey from top-down control, destabilizing lower trophic levels."}],"e22":[{"s":1,"e":19,"q":"What does the 2nd Law of Thermodynamics explain about ecosystems?","opts":["Energy is created by plants from nothing","Energy transformations are inefficient and always lose heat, increasing entropy","Matter cannot be recycled","Food chains can have unlimited trophic levels"],"a":1,"exp":"Every energy conversion loses usable energy as heat via cellular respiration, limiting energy passed up food chains."},{"s":20,"e":33,"q":"How do decomposers (bacteria/fungi) and detritivores differ from producers?","opts":["They convert sunlight into glucose","They gain chemical energy from dead organic matter and recycle nutrients back to soil","They occupy trophic level 1 only","They lose zero energy to respiration"],"a":1,"exp":"Producers are autotrophs making carbon compounds; decomposers and detritivores break down dead organic matter."},{"s":34,"e":44,"q":"By the 10% energy rule, if producers capture 10,000 kJ/m²/yr, roughly how much reaches secondary consumers (Trophic Level 3)?","opts":["9,000 kJ","1,000 kJ","100 kJ","10 kJ"],"a":2,"exp":"Producers (10,000 kJ) -> Primary consumers (~1,000 kJ) -> Secondary consumers (~100 kJ), with ~90% lost at each step."},{"s":45,"e":50,"q":"If a producer fixes GPP = 2,400 kJ/m²/yr and uses R = 900 kJ/m²/yr in respiration, what is NPP? And what is GSP for a consumer?","opts":["NPP = 1,500; GSP = food eaten - faecal loss","NPP = 3,300; GSP = food eaten + faecal loss","NPP = 900; GSP = GPP - R","NPP = 2,400; GSP = NSP + GPP"],"a":0,"exp":"NPP = GPP - R = 2,400 - 900 = 1,500. Consumer Gross Secondary Productivity is GSP = food eaten - faecal loss (and NSP = GSP - R)."},{"s":51,"e":65,"q":"Why is a Pyramid of Energy (Productivity) NEVER inverted, unlike a Pyramid of Biomass?","opts":["Top predators store more sunlight","Energy flow per year must decrease upward due to 2nd Law heat losses, while biomass is a single-day snapshot","Phytoplankton always weigh more than whales","Energy increases at higher levels"],"a":1,"exp":"Fast-reproducing phytoplankton can have lower standing biomass than zooplankton on one day, but annual energy flow always drops upward."},{"s":66,"e":86,"q":"Distinguish bioaccumulation from biomagnification:","opts":["Bioaccumulation is toxin buildup in one organism over time; biomagnification is concentration increasing up trophic levels","They are identical processes","Biomagnification only happens in plants","Bioaccumulation destroys DDT immediately"],"a":0,"exp":"Non-biodegradable toxins like mercury or DDT accumulate inside an individual (bioaccumulation) and concentrate up food chains (biomagnification)."}],"e23":[{"s":1,"e":15,"q":"In the Global Carbon Cycle diagram (Slide 14), what do the RED arrows (burning, farming, fossil fuel combustion) show?","opts":["Natural photosynthesis sinks","Human activities releasing extra CO2 into the atmosphere faster than natural sinks absorb it","Deep ocean downwelling","Rock sedimentation"],"a":1,"exp":"Red arrows show human carbon sources (6 GT/yr fossil fuel burning, forest burning, farming) disrupting dynamic equilibrium."},{"s":1,"e":15,"q":"Which of these is an INORGANIC carbon store rather than an organic store?","opts":["Living organisms","Crude oil and natural gas","Atmosphere, soils, and oceans","Tree biomass"],"a":2,"exp":"Atmosphere, soils, oceans, and limestone are inorganic carbon stores; organisms and fossil fuels are organic stores."},{"s":16,"e":25,"q":"What is carbon sequestration (2.3.5)?","opts":["Burning coal for electricity","Capturing gaseous atmospheric CO2 and storing it in solid or liquid form","Releasing soil carbon through ploughing","Melting permafrost"],"a":1,"exp":"Trees sequester carbon naturally by turning atmospheric CO2 into solid biomass; fossilization locked ancient carbon underground."},{"s":26,"e":39,"q":"How do a young growing forest, a mature climax forest, and a burning forest act in the carbon cycle?","opts":["Young = sink, Mature = store, Burning = source","Young = source, Mature = sink, Burning = store","All three are carbon sinks","Mature forests emit 10x more CO2 than coal"],"a":0,"exp":"Young forest (photosynthesis > R) = net sink; mature forest (balanced) = store; burning/deforested forest (net release) = source."},{"s":40,"e":46,"q":"How does increased ocean CO2 uptake harm coral reefs and shellfish?","opts":["It makes ocean water too alkaline","Dissolved CO2 lowers ocean pH (acidification) and reduces carbonate ions needed for CaCO3 shells","It freezes surface oceans","It increases sunlight underwater"],"a":1,"exp":"Ocean acidification lowers pH and reduces carbonate ion availability, interfering with calcium carbonate deposition in shells and coral skeletons."}]};
